package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.database.Cursor;import android.os.Bundle;import android.provider.ContactsContract.CommonDataKinds.Phone;import android.telephony.PhoneNumberUtils;import java.util.*;
/** Review only: never merges or deletes address-book records. */
public final class ContactDuplicatesActivity extends LeoActivity {
 static String key(String number){String n=PhoneNumberUtils.normalizeNumber(number==null?"":number);return n.replaceFirst("^00","+");}
 protected void onCreate(Bundle b){super.onCreate(b);load();}
 private void load(){begin(L.t("Numere duplicate"));root.addView(text(L.t("Se încarcă…"),16));footer("","",L.t("Înapoi"));worker.execute(new Runnable(){public void run(){final TreeMap<String,LinkedHashMap<Long,String>> groups=new TreeMap<String,LinkedHashMap<Long,String>>();boolean failed=false;try(Cursor r=getContentResolver().query(Phone.CONTENT_URI,new String[]{"contact_id","display_name","data1"},null,null,null)){int count=0;while(r!=null&&r.moveToNext()&&count++<20000){String k=key(r.getString(2));if(k.length()<3)continue;if(!groups.containsKey(k))groups.put(k,new LinkedHashMap<Long,String>());groups.get(k).put(r.getLong(0),r.getString(1));}}catch(RuntimeException e){failed=true;}final boolean error=failed;ui(new Runnable(){public void run(){final ArrayList<String> keys=new ArrayList<String>(),labels=new ArrayList<String>();for(String k:groups.keySet())if(groups.get(k).size()>1){keys.add(k);labels.add(k+"\n"+groups.get(k).size()+L.t(" contacte"));}list(L.t("Numere duplicate"),labels,0,new Choice(){public void pick(int n){final LinkedHashMap<Long,String> group=groups.get(keys.get(n));final ArrayList<Long> ids=new ArrayList<Long>(group.keySet());list(keys.get(n),new ArrayList<String>(group.values()),0,new Choice(){public void pick(int i){startActivity(new Intent(ContactDuplicatesActivity.this,ContactsActivity.class).putExtra("contact_id",ids.get(i)));}},"",null);back=new Runnable(){public void run(){load();}};}},L.t("Reîncarcă"),new Runnable(){public void run(){load();}});if(error)notice(L.t("Contactele nu pot fi citite"));else if(keys.isEmpty())notice(L.t("Niciun număr duplicat între contacte"));}});}});}
}
